// Validate input and map genre to style guidelines
const item = $input.item.json;

const topic = (item.topic || '').trim();
const genre = (item.genre || '').trim();

const genreStyles = {
  tragedy: { tone: 'somber, weighty, inevitable', pacing: 'slow-building with a devastating climax', defaultScenesPerAct: 3 },
  comedy: { tone: 'light, witty, fast-talking', pacing: 'quick, punchy scenes with comic timing', defaultScenesPerAct: 4 },
  thriller: { tone: 'tense, suspicious, high-stakes', pacing: 'escalating tension with cliffhanger scene breaks', defaultScenesPerAct: 4 },
  romance: { tone: 'warm, yearning, emotionally intimate', pacing: 'slow-burn with tender turning points', defaultScenesPerAct: 3 },
  'historical drama': { tone: 'formal, sweeping, era-authentic', pacing: 'measured with rich period detail', defaultScenesPerAct: 3 },
  'sci-fi drama': { tone: 'reflective, speculative, human-centered', pacing: 'idea-driven with grounded emotional stakes', defaultScenesPerAct: 3 },
  'family drama': { tone: 'intimate, layered, bittersweet', pacing: 'conversational with slow-reveal secrets', defaultScenesPerAct: 3 },
  courtroom: { tone: 'sharp, procedural, morally charged', pacing: 'argument-and-reveal structure', defaultScenesPerAct: 4 },
  mystery: { tone: 'curious, guarded, clue-driven', pacing: 'steady reveals building to a twist', defaultScenesPerAct: 4 },
  default: { tone: 'grounded and emotionally honest', pacing: 'balanced rise and fall across acts', defaultScenesPerAct: 3 }
};

const style = genreStyles[genre] || genreStyles.default;
const tone = item.tone && item.tone.length > 0 ? item.tone : style.tone;

let numberOfActs = parseInt(item.numberOfActs, 10);
if (isNaN(numberOfActs) || numberOfActs < 1) numberOfActs = 3;
if (numberOfActs > 5) numberOfActs = 5;

const hasValidInput = topic.length > 0 && genre.length > 0;

return {
  json: {
    ...item,
    topic,
    genre,
    tone,
    numberOfActs,
    scenesPerAct: style.defaultScenesPerAct,
    pacingNotes: style.pacing,
    hasValidInput
  }
};

parameters.text:
=You are a professional dramaturg. Create a complete story blueprint for a {{ $json.genre }} script about: "{{ $json.topic }}".

Tone: {{ $json.tone }}
Pacing notes: {{ $json.pacingNotes }}
Number of acts: {{ $json.numberOfActs }}
Scenes per act (target): {{ $json.scenesPerAct }}

Respond with ONLY valid JSON, no commentary, no code fences, in exactly this shape:
{
  "title": string,
  "logline": string,
  "themes": string[],
  "setting": string,
  "characters": [ { "name": string, "role": string, "age": string, "description": string, "wantVsNeed": string, "arc": string } ],
  "actBreakdown": [ { "actNumber": number, "actTitle": string, "scenes": [ { "sceneNumber": number, "sceneTitle": string, "location": string, "summary": string, "charactersPresent": string[], "emotionalBeat": string } ] } ]
}

