// Parse the outline JSON from the AI response, tolerating stray text/code fences
const item = $input.item.json;
const raw = item.output || item.response || item.text || '';

let cleaned = raw.trim();
cleaned = cleaned.replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();

let outline;
try {
  outline = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  outline = match ? JSON.parse(match[0]) : { error: 'Failed to parse outline JSON', raw: cleaned };
}

return {
  json: {
    requestId: $('Set - Prepare Script Parameters').item.json.requestId,
    requestTimestamp: $('Set - Prepare Script Parameters').item.json.requestTimestamp,
    topic: $('Set - Prepare Script Parameters').item.json.topic,
    genre: $('Set - Prepare Script Parameters').item.json.genre,
    tone: $('Set - Prepare Script Parameters').item.json.tone,
    numberOfActs: $('Set - Prepare Script Parameters').item.json.numberOfActs,
    outline
  }
};

