// Merge outline + full script + production notes into one final payload
const item = $input.item.json;
const raw = item.output || item.response || item.text || '';

let cleaned = raw.trim();
cleaned = cleaned.replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();

let productionNotes;
try {
  productionNotes = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  productionNotes = match ? JSON.parse(match[0]) : { error: 'Failed to parse production notes JSON', raw: cleaned };
}

const prior = $('Code - Parse Full Script JSON').item.json;
const acts = prior.script?.acts || [];

let sceneCount = 0;
let wordCount = 0;
for (const act of acts) {
  for (const scene of (act.scenes || [])) {
    sceneCount += 1;
    wordCount += (scene.stageDirections || '').split(/\s+/).filter(Boolean).length;
    for (const line of (scene.dialogue || [])) {
      wordCount += (line.line || '').split(/\s+/).filter(Boolean).length;
    }
  }
}

return {
  json: {
    success: true,
    requestId: prior.requestId,
    requestTimestamp: prior.requestTimestamp,
    topic: prior.topic,
    genre: prior.genre,
    tone: prior.tone,
    title: prior.outline?.title,
    logline: prior.outline?.logline,
    themes: prior.outline?.themes,
    setting: prior.outline?.setting,
    characters: prior.outline?.characters,
    numberOfActs: prior.numberOfActs,
    numberOfScenes: sceneCount,
    wordCount,
    acts,
    productionNotes,
    logDate: new Date().toISOString().split('T')[0],
    logTimestamp: new Date().toISOString()
  }
};
